import hashlib,json,platform
from pathlib import Path
from rdkit import rdBase
H=Path(__file__).resolve().parent;ROOT=H.parent;E=H/'evaluation';D=H/'NSC-002'
read=lambda p:json.loads(p.read_text(encoding='utf-8-sig'))
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
def write(p,x):p.write_text(json.dumps(x,indent=2,ensure_ascii=False)+'\n',encoding='utf8')
dev=read(E/'development_results.json');held=read(E/'heldout_results.json');old=read(E/'nsc001_regression.json');coverage=read(E/'nsc002_81_case_applicability.json');local=read(E/'local_eligibility_comparison.json')
result={'status':'PROVISIONAL_CHEMICAL_REVIEW_PENDING','development':dev,'public_heldout':held,'blinded':'NOT_RUN','all_controls_correct':dev['counts']['correct']==dev['counts']['total'] and held['counts']['correct']==held['counts']['total']}
write(E/'nsc002_semantic_results.json',result);write(H/'architecture_B/nsc002_results.json',result)
write(E/'extensibility_assessment.json',{'status':'PROVISIONAL','reused_unchanged':['NSC-001 SemanticInterpretation and SemanticValidation dataclasses','NSC-001 JSON Schema field layout and referential integrity checker','result taxonomy and identity boundary','strict parsing and symmetry principles'], 'new':['whole-name grammar and source-span parsing','benzene parent and locant semantics','multiple prefix operations and joint constraint results','nitro internal-charge-aware candidate validation','ring-dihedral comparator and unsupported-form abstention'], 'modified_shared_files':[],'new_dependencies':[],'nsc001_shared_comparator':'Not directly reused: its generic parse rejects every charged atom and would reject the neutral nitro resonance form; the new narrow comparator reuses the graph/symmetry method rather than weakening the old check.','partial_names':'Not implemented: unsupported surrounding syntax may change ownership; no substring-based support.','limits':['Named-suffix and charge/protonation operations not implemented.','No support for arbitrary benzene substituents, charges, stereochemistry, isotopes or mixtures.','Multiple group comparison is joint; per-group differences are not attributed.']})
write(E/'test_results.json',{'nsc002_unit_tests':{'passed':8,'failed':0,'skipped':0},'nsc002_development':dev['counts'],'nsc002_public_heldout':held['counts'],'nsc001_existing_unit_tests':{'passed':11,'failed':0,'skipped':0},'nsc001_previous_controls_replayed':{'passed':18,'failed':0,'skipped':0},'retained_resolver_tests':{'passed':201,'failed':0,'skipped':0},'historical_safety':read(ROOT/'source_aware_substitution_poc/safety_results.json'),'opsin_specific_tests':'NOT_RUN: no OPSIN artifact was modified or directly used for NSC-002 implementation; historical safety helper may invoke the existing diagnostic adapter.','python_version':platform.python_version(),'rdkit_version':rdBase.rdkitVersion,'human_review':'PENDING'})
pre=read(E/'pre_implementation_hashes.json')['files'];production={n:sha(ROOT/n)==v for n,v in pre.items()}
contract=read(D/'benchmark_freeze.json')['sha256'];contract_checks={n:sha(D/n)==v for n,v in contract.items()}
impl=read(E/'implementation_freeze.json')['sha256'];impl_checks={n:sha(H/n)==v for n,v in impl.items()}
oldfreeze=read(ROOT/'nsc_architecture_experiment/NSC-001/benchmark_freeze.json')['sha256'];old_checks={n:sha(ROOT/'nsc_architecture_experiment'/n)==v for n,v in oldfreeze.items()}
integrity={'selected_production_files_unchanged':production,'nsc002_contract_and_benchmark_unchanged':contract_checks,'nsc002_implementation_unchanged_since_development':impl_checks,'nsc001_frozen_contract_and_controls_unchanged':old_checks,'nsc001_semantic_regression':old['status'],'registry':'No registry writes issued; full before/after registry hash not taken.','provider_calls':'No resolver provider calls were introduced; IUPAC/PubChem public reference pages were searched for grounding.','pass':all(production.values()) and all(contract_checks.values()) and all(impl_checks.values()) and all(old_checks.values()) and old['status']=='PASS'}
write(E/'integrity_report.json',integrity);assert integrity['pass']
print(json.dumps({'development':dev['counts'],'public_heldout':held['counts'],'nsc001':old['status'],'coverage':coverage['summary'],'existing_local_baseline':{'correct_eligible':local['metrics']['correct_retained'],'correct_withheld':local['metrics']['correct_newly_withheld']},'integrity':'PASS'},indent=2))
